//! 原文を読み、照合し、取得する。
//!
//! **原文を連結しない。** 位置をたどれる形のまま持つ ── 連結すると、どの原文の
//! どこで一致したかが報告できない。
//!
//! **読めなかったものを、黙って除外しない。** 除外すると、0件が「無い」なのか
//! 「読めなかっただけ」なのかを、読み手が区別できない。
//!
//! **行の区切りを1つへ統一してから読む。** 原文には CR 単独で行を区切るものが在る
//! （実測 ── PDF から起こした原文が CR を 11,526 件持っていた）。統一しないと、
//! 報告する行が読み手の見る行と食い違う。

use std::io;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use crate::find::{self, How};

/// 1つの原文で読む上限（バイト）。
pub const MAX_BYTES: u64 = 4_000_000;

/// 見ない包み。
const SKIP: [&str; 7] = [
    ".git",
    "node_modules",
    "target",
    "dist",
    "build",
    ".venv",
    "__pycache__",
];

/// 原文1つ。**位置をたどれる形で持つ。**
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Doc {
    /// 呼ぶ側へ見せる名前。
    pub name: String,
    /// 中身。
    pub text: String,
    /// 行の頭の位置（文字で数える）。
    starts: Vec<usize>,
}

impl Doc {
    /// 原文を組む。
    #[must_use]
    pub fn new(name: String, text: String) -> Self {
        let mut starts = vec![0];
        for (i, c) in text.chars().enumerate() {
            if c == '\n' {
                starts.push(i + 1);
            }
        }
        Self { name, text, starts }
    }

    /// その位置が何行目かを返す（1から数える）。
    #[must_use]
    pub fn line_of(&self, offset: usize) -> usize {
        self.starts.partition_point(|s| *s <= offset)
    }

    /// その行の中身を返す。
    #[must_use]
    pub fn line_text(&self, line: usize) -> String {
        let Some(a) = self.starts.get(line.saturating_sub(1)) else {
            return String::new();
        };
        let chars: Vec<char> = self.text.chars().collect();
        let b = self.starts.get(line).copied().unwrap_or(chars.len());
        chars[*a..b.min(chars.len())]
            .iter()
            .collect::<String>()
            .trim_end_matches('\n')
            .to_owned()
    }
}

/// 一致1件。
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Hit {
    /// どの原文か。
    pub doc: String,
    /// 何行目か。
    pub line: usize,
    /// その行の中身。
    pub excerpt: String,
}

/// 1つの語の照合の結果。
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Found {
    /// 照合した語。
    pub needle: String,
    /// 一致した箇所。
    pub hits: Vec<Hit>,
}

/// 照合の全体。**見つかった位置と、読めなかった範囲を必ず一緒に持つ。**
#[derive(Debug, Clone, Default)]
#[non_exhaustive]
pub struct Scan {
    /// 語ごとの結果。
    pub results: Vec<Found>,
    /// 読めなかったものと、その理由。
    pub unreadable: Vec<(String, String)>,
    /// 読めた原文の数。
    pub docs_read: usize,
}

impl Scan {
    /// 0件を「無い」と結論してよいか。**読めなかった範囲が在るなら、よくない。**
    #[must_use]
    pub fn can_conclude_absent(&self) -> bool {
        self.unreadable.is_empty()
    }

    /// 一致が1件も無かった語。
    #[must_use]
    pub fn missing(&self) -> Vec<&Found> {
        self.results.iter().filter(|r| r.hits.is_empty()).collect()
    }
}

fn walk(dir: &Path, base: &Path, out: &mut Vec<(PathBuf, String)>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    let mut paths: Vec<PathBuf> = entries.flatten().map(|e| e.path()).collect();
    paths.sort();
    for p in paths {
        let name = p
            .file_name()
            .unwrap_or_default()
            .to_string_lossy()
            .into_owned();
        if p.is_dir() {
            if !SKIP.contains(&name.as_str()) {
                walk(&p, base, out);
            }
        } else if !name.ends_with(".meta.json") {
            let rel = p.strip_prefix(base).unwrap_or(&p).display().to_string();
            out.push((p.clone(), rel));
        }
    }
}

/// 行の区切りを LF へ統一する。**CR 単独と CRLF の両方を直す。**
#[must_use]
pub fn normalize(text: &str) -> String {
    if !text.contains('\r') {
        return text.to_owned();
    }
    text.replace("\r\n", "\n").replace('\r', "\n")
}

/// 原文を読む。**読めなかったものは、黙って除外せず返す。**
#[must_use]
pub fn read_docs(path: &Path, max_bytes: u64) -> (Vec<Doc>, Vec<(String, String)>) {
    let mut files = Vec::new();
    if path.is_file() {
        let name = path
            .file_name()
            .unwrap_or_default()
            .to_string_lossy()
            .into_owned();
        files.push((path.to_path_buf(), name));
    } else if path.is_dir() {
        walk(path, path, &mut files);
    } else {
        return (
            Vec::new(),
            vec![(path.display().to_string(), "在らない".to_owned())],
        );
    }
    let mut docs = Vec::new();
    let mut bad = Vec::new();
    for (file, name) in files {
        let Ok(meta) = std::fs::metadata(&file) else {
            bad.push((name, "開けない".to_owned()));
            continue;
        };
        if meta.len() > max_bytes {
            bad.push((name, format!("大きすぎる（{} バイト）", meta.len())));
            continue;
        }
        match std::fs::read(&file) {
            Ok(raw) => match String::from_utf8(raw) {
                Ok(text) => docs.push(Doc::new(name, normalize(&text))),
                Err(_) => bad.push((name, "文字として読めない".to_owned())),
            },
            Err(e) => bad.push((name, format!("開けない（{e}）"))),
        }
    }
    (docs, bad)
}

/// 原文と照合する。
///
/// **種類は呼ぶ側が渡す** ── 道具の側で「たぶん識別子だろう」と決めない。
/// `near` を渡すと、その語の在る行から `within` 行の内側だけを一致として数える ──
/// **名前が在ることと、その名前がそこで使われることは別である。**
#[must_use]
pub fn scan(
    path: &Path,
    needles: &[String],
    how: How,
    near: Option<&str>,
    within: usize,
    max_bytes: u64,
) -> Scan {
    let (docs, bad) = read_docs(path, max_bytes);
    let mut results = Vec::new();
    for needle in needles {
        let mut hits = Vec::new();
        for doc in &docs {
            let anchors: Option<Vec<usize>> = near.map(|a| {
                find::text(&doc.text, a)
                    .into_iter()
                    .map(|o| doc.line_of(o))
                    .collect()
            });
            for offset in find::find(how, &doc.text, needle) {
                let line = doc.line_of(offset);
                if let Some(anchors) = &anchors {
                    if !anchors.iter().any(|a| line.abs_diff(*a) <= within) {
                        continue;
                    }
                }
                hits.push(Hit {
                    doc: doc.name.clone(),
                    line,
                    excerpt: doc.line_text(line).trim().to_owned(),
                });
            }
        }
        results.push(Found {
            needle: needle.clone(),
            hits,
        });
    }
    Scan {
        results,
        unreadable: bad,
        docs_read: docs.len(),
    }
}

/// 保存する名前を、出どころから作る。
#[must_use]
pub fn slug(url: &str) -> String {
    let body = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))
        .unwrap_or(url);
    let mut out = String::new();
    let mut last_join = false;
    for c in body.chars() {
        if c.is_ascii_alphanumeric() || c == '.' || c == '_' || c == '-' {
            out.push(c);
            last_join = false;
        } else if !last_join {
            out.push('_');
            last_join = true;
        }
    }
    out.trim_matches('_').chars().take(120).collect()
}

/// 取得したものを原文として受け取るか。
///
/// **記法を剥がしたり変換したりしない** ── 変換した時点で、「原文と1文字ずつ同じ」が
/// 主張できなくなる。
#[must_use]
pub const fn acceptable(code: u32, size: u64) -> bool {
    code == 200 && size > 0
}

/// 取得の記録。
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Fetched {
    /// 保存した場所。
    pub path: PathBuf,
    /// 実際に取得した出どころ。
    pub url: String,
    /// 頼まれた出どころ。
    pub requested: String,
    /// 取得した日時。
    pub fetched_at: String,
    /// 中身の要約。
    pub sha256: String,
    /// バイト数。
    pub bytes: u64,
    /// 行数。
    pub lines: usize,
    /// 種類。
    pub content_type: String,
}

fn sha256_of(data: &[u8]) -> String {
    use sha2::{Digest as _, Sha256};
    Sha256::digest(data)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

fn now() -> String {
    let done = Command::new("date")
        .arg("+%Y-%m-%dT%H:%M:%S%z")
        .stdin(Stdio::null())
        .output()
        .ok();
    done.map_or_else(String::new, |o| {
        String::from_utf8_lossy(&o.stdout).trim().to_owned()
    })
}

/// 原文を取得する。**まず `<出どころ>.md` を試し、無ければ本体を取る。**
///
/// # Errors
///
/// 取得できなかったとき、試した先を添えて返す。
pub fn fetch(url: &str, outdir: &Path) -> io::Result<Fetched> {
    std::fs::create_dir_all(outdir)?;
    let plain = url.ends_with(".md") || url.ends_with(".txt") || url.ends_with(".json");
    let candidates: Vec<String> = if plain {
        vec![url.to_owned()]
    } else {
        vec![format!("{url}.md"), url.to_owned()]
    };
    let mut tried = Vec::new();
    for cand in candidates {
        let path = outdir.join(slug(&cand));
        let done = Command::new("curl")
            .args(["-sSL", "-m", "60", "-A", "Mozilla/5.0", &cand, "-o"])
            .arg(&path)
            .args(["-w", "%{http_code} %{content_type}"])
            .stdin(Stdio::null())
            .output()?;
        let out = String::from_utf8_lossy(&done.stdout).into_owned();
        let mut parts = out.splitn(2, ' ');
        let code: u32 = parts.next().unwrap_or("0").trim().parse().unwrap_or(0);
        let ctype = parts.next().unwrap_or("").trim().to_owned();
        let size = std::fs::metadata(&path).map(|m| m.len()).unwrap_or(0);
        tried.push(format!("  {code}  {size:>9}  {ctype:32}{cand}"));
        if acceptable(code, size) {
            let body = std::fs::read(&path)?;
            return Ok(Fetched {
                sha256: sha256_of(&body),
                bytes: body.len() as u64,
                lines: body.iter().filter(|b| **b == b'\n').count() + 1,
                path,
                url: cand,
                requested: url.to_owned(),
                fetched_at: now(),
                content_type: ctype,
            });
        }
        let _ = std::fs::remove_file(&path); // 受け取らなかったものを残さない
    }
    Err(io::Error::other(format!(
        "取得できなかった。試したもの:\n{}",
        tried.join("\n")
    )))
}

/// 取得の記録を書く。
///
/// # Errors
///
/// 書けないときに返す。
pub fn write_meta(got: &Fetched) -> io::Result<PathBuf> {
    let name = got
        .path
        .file_name()
        .unwrap_or_default()
        .to_string_lossy()
        .into_owned();
    let meta = got.path.with_file_name(format!("{name}.meta.json"));
    let body = serde_json::json!({
        "url": got.url, "requested": got.requested, "fetched_at": got.fetched_at,
        "sha256": got.sha256, "bytes": got.bytes, "lines": got.lines,
        "content_type": got.content_type,
    });
    let text = serde_json::to_string_pretty(&body)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.to_string()))?;
    std::fs::write(&meta, text.replace("  ", " ") + "\n")?;
    Ok(meta)
}

/// 取得したものを並べる。**印字はしない。**
#[must_use]
pub fn listing(outdir: &Path) -> Vec<(String, usize, String)> {
    let Ok(entries) = std::fs::read_dir(outdir) else {
        return Vec::new();
    };
    let mut names: Vec<PathBuf> = entries.flatten().map(|e| e.path()).collect();
    names.sort();
    let mut rows = Vec::new();
    for p in names {
        if !p.to_string_lossy().ends_with(".meta.json") {
            continue;
        }
        let Ok(body) = std::fs::read_to_string(&p) else {
            continue;
        };
        let Ok(meta) = serde_json::from_str::<serde_json::Value>(&body) else {
            continue;
        };
        let at = meta
            .get("fetched_at")
            .and_then(|x| x.as_str())
            .unwrap_or_default();
        rows.push((
            at.chars().take(10).collect(),
            meta.get("lines")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0) as usize,
            meta.get("url")
                .and_then(|x| x.as_str())
                .unwrap_or_default()
                .to_owned(),
        ));
    }
    rows
}

// SPDX-License-Identifier: MIT
//! 原稿から、枚ごとの音声と尺を作る。
//!
//! **同じ文なら作り直さない。** 文 ・ 声 ・ 合成器のどれかが変わればキーも変わる ──
//! 変わっていないものを作り直すと、外へ出す回数だけ費用が増える。
//!
//! **外の道具を呼ぶのは合成だけである。** 尺は音声そのものから測る（`mp3`）。

use std::io;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use serde_json::{json, Value};
use sha2::{Digest as _, Sha256};

use crate::mp3;

/// 読みの印の種類。**1つの引数として渡す** ── 分けると、続く引数まで飲み込む。
const MARK_TYPES: &str = "--speech-mark-types=[\"word\", \"sentence\"]";

/// 合成の制限時間（秒）。
const TIMEOUT: u64 = 300;

/// 原稿1件。
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Item {
    /// 枚の識別子。
    pub id: String,
    /// 読み上げる文。
    pub text: String,
}

/// 原稿の全体。
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Script {
    /// 読み上げる声。
    pub voice: String,
    /// 合成器。
    pub engine: String,
    /// 読みの辞書。
    pub lexicons: Vec<String>,
    /// 取り出しの置き場（原稿の場所からの相対）。
    pub cache: String,
    /// 枚。
    pub items: Vec<Item>,
}

/// キーを作る。**文 ・ 声 ・ 合成器のどれかが変われば、キーも変わる。**
#[must_use]
pub fn key_of(text: &str, voice: &str, engine: &str) -> String {
    let digest = Sha256::digest(format!("{text}|{voice}|{engine}").as_bytes());
    digest.iter().take(8).map(|b| format!("{b:02x}")).collect()
}

/// 原稿を読む。
///
/// # Errors
///
/// 読めないとき、または形が違うときに返す。
pub fn load(dir: &Path) -> io::Result<Script> {
    let body = std::fs::read_to_string(dir.join("narration.json"))?;
    let parsed: Value = serde_json::from_str(&body)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.to_string()))?;
    let text = |key: &str, default: &str| {
        parsed
            .get(key)
            .and_then(Value::as_str)
            .unwrap_or(default)
            .to_owned()
    };
    let items = parsed
        .get("items")
        .and_then(Value::as_array)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "items が無い"))?
        .iter()
        .filter_map(|x| {
            Some(Item {
                id: x.get("id")?.as_str()?.to_owned(),
                text: x.get("text")?.as_str()?.to_owned(),
            })
        })
        .collect();
    Ok(Script {
        voice: text("voice", "Takumi"),
        engine: text("engine", "neural"),
        lexicons: parsed
            .get("lexicons")
            .and_then(Value::as_array)
            .map(|x| {
                x.iter()
                    .filter_map(Value::as_str)
                    .map(str::to_owned)
                    .collect()
            })
            .unwrap_or_default(),
        cache: text("cache", "cache"),
        items,
    })
}

/// 1枚ぶんの見立て。
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Planned {
    /// 枚の識別子。
    pub id: String,
    /// キー。
    pub key: String,
    /// 読み上げる文。
    pub text: String,
    /// 音声の置き場（原稿の場所からの相対）。
    pub audio: String,
    /// 読みの印の置き場。
    pub marks: String,
    /// 既に在るか。
    pub cached: bool,
}

/// 枚ごとに、キーと、合成が要るかどうかを出す。**1件も合成しない。**
#[must_use]
pub fn plan(dir: &Path, script: &Script, voice: &str) -> Vec<Planned> {
    let cache = PathBuf::from(&script.cache);
    script
        .items
        .iter()
        .map(|item| {
            let key = key_of(&item.text, voice, &script.engine);
            let audio = cache.join(format!("{key}.mp3"));
            Planned {
                id: item.id.clone(),
                key: key.clone(),
                text: item.text.clone(),
                cached: dir.join(&audio).exists(),
                audio: audio.display().to_string(),
                marks: cache
                    .join(format!("{key}.marks.json"))
                    .display()
                    .to_string(),
            }
        })
        .collect()
}

fn aws(args: &[&str], out: &Path) -> io::Result<()> {
    let done = Command::new("timeout")
        .arg(TIMEOUT.to_string())
        .arg("aws")
        .args(["polly", "synthesize-speech"])
        .args(args)
        .arg(out)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .output()?;
    if done.status.success() {
        return Ok(());
    }
    Err(io::Error::other(format!(
        "合成できない ── {}",
        String::from_utf8_lossy(&done.stderr).trim()
    )))
}

/// 音声と、語と文の時刻を作る。**どちらも同じ操作から得られる。**
///
/// **値を複数取る引数は `=` で1つにまとめる** ── 分けて渡すと、後ろに続く出力先の
/// 指定まで飲み込み、出力先が無いという誤りになる。
///
/// # Errors
///
/// 合成に失敗したときに返す。
pub fn synthesize(
    text: &str,
    voice: &str,
    engine: &str,
    dest: &Path,
    lexicons: &[String],
) -> io::Result<()> {
    let joined = lexicons.join(" ");
    let mut head: Vec<&str> = vec!["--voice-id", voice, "--engine", engine];
    let with_lexicons = format!("--lexicon-names={joined}");
    if !lexicons.is_empty() {
        head.push(&with_lexicons);
    }
    let mut audio = head.clone();
    audio.extend(["--output-format", "mp3", "--text", text]);
    aws(&audio, &dest.with_extension("mp3"))?;

    let mut marks = head;
    marks.extend(["--output-format", "json", MARK_TYPES, "--text", text]);
    let name = dest
        .file_name()
        .unwrap_or_default()
        .to_string_lossy()
        .into_owned();
    aws(&marks, &dest.with_file_name(format!("{name}.marks.json")))
}

/// 作った結果。
#[derive(Debug, Clone, Default)]
#[non_exhaustive]
pub struct Made {
    /// 新しく合成した枚。
    pub made: Vec<String>,
    /// 取り出した枚。
    pub taken: Vec<String>,
    /// 枚ごとの尺（ミリ秒）。
    pub durations: Vec<(String, u64)>,
}

/// キーが在る枚は取り出し、無い枚だけを合成して、継ぎ目の出力を書く。
///
/// # Errors
///
/// 合成に失敗したとき、または書けないときに返す。
pub fn run(dir: &Path, script: &Script, voice: &str) -> io::Result<Made> {
    let cache = dir.join(&script.cache);
    std::fs::create_dir_all(&cache)?;
    let mut out = Made::default();
    let mut items = Vec::new();
    for row in plan(dir, script, voice) {
        let dest = cache.join(&row.key);
        if dest.with_extension("mp3").exists() {
            out.taken.push(row.id.clone());
        } else {
            synthesize(&row.text, voice, &script.engine, &dest, &script.lexicons)?;
            out.made.push(row.id.clone());
        }
        let data = std::fs::read(dest.with_extension("mp3")).unwrap_or_default();
        let ms = mp3::duration_ms(&data);
        out.durations.push((row.id.clone(), ms));
        items.push(json!({
            "id": row.id, "key": row.key, "audio": row.audio,
            "marks": row.marks, "format": "mp3", "durationMs": ms,
        }));
    }
    let body = json!({ "voice": voice, "engine": script.engine, "items": items });
    let text = serde_json::to_string_pretty(&body)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.to_string()))?;
    std::fs::write(dir.join("narration.out.json"), text + "\n")?;
    Ok(out)
}

/// 読みの辞書を登録する。**合成の前に、入力へ適用される。**
///
/// # Errors
///
/// 登録に失敗したときに返す。
pub fn put_lexicon(path: &Path, name: &str) -> io::Result<()> {
    let content = format!("file://{}", path.display());
    let done = Command::new("timeout")
        .arg("60")
        .arg("aws")
        .args([
            "polly",
            "put-lexicon",
            "--name",
            name,
            "--content",
            &content,
        ])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .output()?;
    if done.status.success() {
        return Ok(());
    }
    let why: String = String::from_utf8_lossy(&done.stderr)
        .trim()
        .chars()
        .take(300)
        .collect();
    Err(io::Error::other(why))
}

